-- Label foto opsional: penilaian utama menggunakan kecocokan objek dan kualitas foto.

update public.quest_teks set pertanyaan='Temukan fosil tulang lengan (humerus) Megalochelys, si kura-kura raksasa. Foto fosilnya dengan jelas!',
  target_foto='Fosil tulang lengan (humerus) Megalochelys sp. terlihat jelas. Label nama boleh ikut terlihat sebagai bukti tambahan, tetapi tidak wajib.',
  kriteria_foto='Lolos jika objek koleksi sesuai dengan target quest dan terlihat jelas. Label nama bersifat opsional sebagai bukti tambahan. Foto buram, gelap, atau kecocokan objek yang belum dapat dipastikan diminta ulang.'
where id_quest='40000000-0000-4000-8000-000000000001' and bahasa='id';

update public.quest_teks set pertanyaan='Di sini ada beberapa jenis karang. Ada yang bercabang, ada yang pipih, dan ada yang membulat. Temukan karang yang bentuknya membulat seperti kepala, yang disebut head coral. Foto karangnya dengan jelas!',
  target_foto='Head coral (karang membulat seperti kepala) terlihat jelas. Label nama boleh ikut terlihat sebagai bukti tambahan, tetapi tidak wajib.',
  kriteria_foto='Lolos jika objek koleksi sesuai dengan target quest dan terlihat jelas. Label nama bersifat opsional sebagai bukti tambahan. Foto buram, gelap, atau kecocokan objek yang belum dapat dipastikan diminta ulang.'
where id_quest='40000000-0000-4000-8000-000000000024' and bahasa='id';

